  3→use crate::error::ProtocolError;
  4→use crate::refspec::{ensure_refspecs, ENGRAM_FETCH_REFSPEC, ENGRAM_PUSH_REFSPEC};
  5→
  6→/// Options for push/fetch operations.
  7→#[derive(Debug, Default)]
  8→pub struct SyncOptions {
  9→    /// Only sync these specific engram ref patterns (empty = all).
 10→    pub refspecs: Vec<String>,
 11→    /// Dry run — don't actually transfer data.
 12→    pub dry_run: bool,
 13→}
 14→
 15→/// Result of a push operation.
 16→#[derive(Debug)]
 17→pub struct PushResult {
 18→    pub remote: String,
 19→    pub refs_pushed: usize,
 20→}
 21→
 22→/// Result of a fetch operation.
 23→#[derive(Debug)]
 24→pub struct FetchResult {
 25→    pub remote: String,
 26→    pub refs_fetched: usize,
 27→}
 28→
 29→/// Push engram refs to a remote.
 30→pub fn push_engrams(
 31→    repo: &Repository,
 32→    remote_name: &str,
 33→    opts: &SyncOptions,
 34→) -> Result<PushResult, ProtocolError> {
 35→    ensure_refspecs(repo, remote_name)?;
 36→
 37→    let refspecs = if opts.refspecs.is_empty() {
 38→        vec![ENGRAM_PUSH_REFSPEC.to_string()]
 39→    } else {
 40→        opts.refspecs.clone()
 41→    };
 42→
 43→    if opts.dry_run {
 44→        // Count refs that would be pushed
 45→        let refs = engram_core::storage::refs::list_engram_refs(repo)?;
 46→        return Ok(PushResult {
 47→            remote: remote_name.into(),
 48→            refs_pushed: refs.len(),
 49→        });
 50→    }
 51→
 52→    let mut remote = repo
 53→        .find_remote(remote_name)
 54→        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;
 55→
 56→    let refspec_strs: Vec<&str> = refspecs.iter().map(|s| s.as_str()).collect();
 57→
 58→    remote
 59→        .push(&refspec_strs, None)
 60→        .map_err(|e| ProtocolError::Sync(format!("Push failed: {e}")))?;
 61→
 62→    // Count refs (approximate)
 63→    let refs = engram_core::storage::refs::list_engram_refs(repo)?;
 64→
 65→    Ok(PushResult {
 66→        remote: remote_name.into(),
 67→        refs_pushed: refs.len(),
 68→    })
 69→}
 70→
 71→/// Fetch engram refs from a remote.
 72→pub fn fetch_engrams(
 73→    repo: &Repository,
 74→    remote_name: &str,
 75→    opts: &SyncOptions,
 76→) -> Result<FetchResult, ProtocolError> {
 77→    ensure_refspecs(repo, remote_name)?;
 78→
 79→    let refspecs = if opts.refspecs.is_empty() {
 80→        vec![ENGRAM_FETCH_REFSPEC.to_string()]
 81→    } else {
 82→        opts.refspecs.clone()
 83→    };
 84→
 85→    if opts.dry_run {
 86→        return Ok(FetchResult {
 87→            remote: remote_name.into(),
 88→            refs_fetched: 0,
 89→        });
 90→    }
 91→
 92→    let refs_before = engram_core::storage::refs::list_engram_refs(repo)?;
 93→
 94→    let mut remote = repo
 95→        .find_remote(remote_name)
 96→        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;
 97→
 98→    let refspec_strs: Vec<&str> = refspecs.iter().map(|s| s.as_str()).collect();
 99→
100→    remote
101→        .fetch(&refspec_strs, None, None)
102→        .map_err(|e| ProtocolError::Sync(format!("Fetch failed: {e}")))?;
103→
104→    let refs_after = engram_core::storage::refs::list_engram_refs(repo)?;
105→    let new_refs = refs_after.len().saturating_sub(refs_before.len());
106→
107→    Ok(FetchResult {
108→        remote: remote_name.into(),
109→        refs_fetched: new_refs,
110→    })
111→}
