 6→
 7→/// An entry in a file's reasoning trace.
 8→#[derive(Debug, Clone)]
 9→pub struct TraceEntry {
10→    pub manifest: Manifest,
11→    pub change_type: String,
12→}
13→
14→/// Trace all engrams that touched a file, ordered by time.
15→pub fn trace_file(
16→    storage: &GitStorage,
17→    search: &SearchEngine,
18→    file_path: &str,
19→) -> Result<Vec<TraceEntry>, QueryError> {
20→    let results = search.search_by_file(storage, file_path, 100)?;
21→
22→    let mut entries: Vec<TraceEntry> = results
23→        .into_iter()
24→        .map(|r| {
25→            // Fetch the full engram to get actual change type for this file
26→            let change_type = storage
27→                .read(r.manifest.id.as_str())
28→                .ok()
29→                .and_then(|data| {
30→                    data.operations
31→                        .file_changes
32→                        .iter()
33→                        .find(|fc| fc.path == file_path)
34→                        .map(|fc| match &fc.change_type {
35→                            engram_core::model::FileChangeType::Created => "created".to_string(),
36→                            engram_core::model::FileChangeType::Modified => "modified".to_string(),
37→                            engram_core::model::FileChangeType::Deleted => "deleted".to_string(),
38→                            engram_core::model::FileChangeType::Renamed { from } => {
39→                                format!("renamed from {from}")
40→                            }
41→                        })
42→                })
43→                .unwrap_or_else(|| "modified".to_string());
44→            TraceEntry {
45→                manifest: r.manifest,
46→                change_type,
47→            }
48→        })
49→        .collect();
50→
51→    // Sort by creation time (oldest first for a trace)
52→    entries.sort_by_key(|e| e.manifest.created_at);
53→
54→    Ok(entries)
55→}
