  8→/// Differences between two engrams.
  9→#[derive(Debug)]
 10→pub struct EngramDiff {
 11→    pub id_a: EngramId,
 12→    pub id_b: EngramId,
 13→    pub common_files: Vec<String>,
 14→    pub only_a_files: Vec<String>,
 15→    pub only_b_files: Vec<String>,
 16→    pub token_delta: i64,
 17→    pub cost_delta: Option<f64>,
 18→}
 19→
 20→/// Compare two engrams.
 21→pub fn diff_engrams(
 22→    storage: &GitStorage,
 23→    id_a: &EngramId,
 24→    id_b: &EngramId,
 25→) -> Result<EngramDiff, QueryError> {
 26→    let data_a = storage.read(id_a.as_str())?;
 27→    let data_b = storage.read(id_b.as_str())?;
 28→
 29→    compute_diff(id_a, id_b, &data_a, &data_b)
 30→}
 31→
 32→fn compute_diff(
 33→    id_a: &EngramId,
 34→    id_b: &EngramId,
 35→    data_a: &EngramData,
 36→    data_b: &EngramData,
 37→) -> Result<EngramDiff, QueryError> {
 38→    let files_a: HashSet<&str> = data_a
 39→        .operations
 40→        .file_changes
 41→        .iter()
 42→        .map(|f| f.path.as_str())
 43→        .collect();
 44→    let files_b: HashSet<&str> = data_b
 45→        .operations
 46→        .file_changes
 47→        .iter()
 48→        .map(|f| f.path.as_str())
 49→        .collect();
 50→
 51→    let common: Vec<String> = files_a
 52→        .intersection(&files_b)
 53→        .map(|s| s.to_string())
 54→        .collect();
 55→    let only_a: Vec<String> = files_a
 56→        .difference(&files_b)
 57→        .map(|s| s.to_string())
 58→        .collect();
 59→    let only_b: Vec<String> = files_b
 60→        .difference(&files_a)
 61→        .map(|s| s.to_string())
 62→        .collect();
 63→
 64→    let token_delta = data_b.manifest.token_usage.total_tokens as i64
 65→        - data_a.manifest.token_usage.total_tokens as i64;
 66→
 67→    let cost_delta = match (
 68→        data_a.manifest.token_usage.cost_usd,
 69→        data_b.manifest.token_usage.cost_usd,
 70→    ) {
 71→        (Some(a), Some(b)) => Some(b - a),
 72→        _ => None,
 73→    };
 74→
 75→    Ok(EngramDiff {
 76→        id_a: id_a.clone(),
 77→        id_b: id_b.clone(),
 78→        common_files: common,
 79→        only_a_files: only_a,
 80→        only_b_files: only_b,
 81→        token_delta,
 82→        cost_delta,
 83→    })
 84→}
