230→    #[tool(
231→        description = "List recent engrams (most recent first). Shows ID, agent, model, date, and summary."
232→    )]
233→    fn engram_log(&self, Parameters(params): Parameters<LogParams>) -> Result<String, String> {
234→        let storage = self.open_storage()?;
235→        let opts = ListOptions {
236→            limit: Some(params.limit.unwrap_or(10)),
237→            agent_filter: params.by_agent.clone(),
238→        };
239→        let manifests = storage
240→            .list(&opts)
241→            .map_err(|e| format!("Failed to list engrams: {e}"))?;
242→
243→        if manifests.is_empty() {
244→            return Ok("No engrams found.".to_string());
245→        }
246→
247→        let mut out = format!("{} engram(s):\n\n", manifests.len());
248→        for m in &manifests {
249→            let short_id = &m.id.as_str()[..8.min(m.id.as_str().len())];
250→            let summary = m.summary.as_deref().unwrap_or("(no summary)");
251→            let agent = &m.agent.name;
252→            let model = m.agent.model.as_deref().unwrap_or("");
253→            let date = m.created_at.format("%Y-%m-%d %H:%M");
254→            let tokens = m.token_usage.total_tokens;
255→            let cost = m
256→                .token_usage
