 42→    pub edges: Vec<GraphEdge>,
 43→}
 44→
 45→impl ContextGraph {
 46→    /// Extract a subgraph centered on a node, up to a given depth.
 47→    pub fn subgraph(&self, center_id: &str, depth: usize) -> ContextGraph {
 48→        use std::collections::{HashSet, VecDeque};
 49→
 50→        let mut visited = HashSet::new();
 51→        let mut queue = VecDeque::new();
 52→        queue.push_back((center_id.to_string(), 0));
 53→        visited.insert(center_id.to_string());
 54→
 55→        while let Some((current, d)) = queue.pop_front() {
 56→            if d >= depth {
 57→                continue;
 58→            }
 59→            for edge in &self.edges {
 60→                let neighbor = if edge.from == current {
 61→                    &edge.to
 62→                } else if edge.to == current {
 63→                    &edge.from
 64→                } else {
 65→                    continue;
 66→                };
 67→                if visited.insert(neighbor.clone()) {
 68→                    queue.push_back((neighbor.clone(), d + 1));
 69→                }
 70→            }
 71→        }
 72→
 73→        let nodes: Vec<GraphNode> = self
 74→            .nodes
 75→            .iter()
 76→            .filter(|n| visited.contains(&n.id))
 77→            .cloned()
 78→            .collect();
 79→        let edges: Vec<GraphEdge> = self
 80→            .edges
 81→            .iter()
 82→            .filter(|e| visited.contains(&e.from) && visited.contains(&e.to))
 83→            .cloned()
 84→            .collect();
 85→
 86→        ContextGraph { nodes, edges }
 87→    }
 88→
 89→    /// Render as DOT format for Graphviz.
 90→    pub fn to_dot(&self) -> String {
 91→        let mut dot = String::from("digraph engram {\n  rankdir=LR;\n");
 92→
 93→        for node in &self.nodes {
 94→            let shape = match node.node_type {
 95→                NodeType::Engram => "box",
 96→                NodeType::File => "note",
 97→                NodeType::Agent => "diamond",
 98→                NodeType::Commit => "ellipse",
 99→            };
100→            dot.push_str(&format!(
101→                "  \"{}\" [label=\"{}\" shape={}];\n",
102→                node.id, node.label, shape
103→            ));
104→        }
105→
106→        for edge in &self.edges {
107→            let label = match edge.edge_type {
108→                EdgeType::ModifiedBy => "modified_by",
109→                EdgeType::ProducedBy => "produced_by",
110→                EdgeType::UsedAgent => "used_agent",
111→                EdgeType::FollowsFrom => "follows_from",
112→                EdgeType::TouchedFile => "touched_file",
113→            };
114→            dot.push_str(&format!(
115→                "  \"{}\" -> \"{}\" [label=\"{}\"];\n",
116→                edge.from, edge.to, label
117→            ));
118→        }
119→
120→        dot.push_str("}\n");
121→        dot
122→    }
123→}
