  1→use std::collections::HashSet;
  2→
  3→use engram_core::storage::GitStorage;
  4→
  5→use super::model::*;
  6→use crate::error::QueryError;
  7→
  8→/// Build a context graph from all engrams in storage.
  9→pub fn build_graph(storage: &GitStorage) -> Result<ContextGraph, QueryError> {
 10→    let manifests = storage.list(&Default::default())?;
 11→    let mut graph = ContextGraph::default();
 12→    let mut seen_agents = HashSet::new();
 13→    let mut seen_files = HashSet::new();
 14→    let mut seen_commits = HashSet::new();
 15→
 16→    for manifest in &manifests {
 17→        let data = match storage.read(manifest.id.as_str()) {
 18→            Ok(d) => d,
 19→            Err(e) => {
 20→                tracing::warn!("Failed to read engram {}: {e}", manifest.id);
 21→                continue;
 22→            }
 23→        };
 24→
 25→        let engram_node_id = format!("engram:{}", manifest.id.as_str());
 26→
 27→        // Add engram node
 28→        graph.nodes.push(GraphNode {
 29→            id: engram_node_id.clone(),
 30→            node_type: NodeType::Engram,
 31→            label: manifest
 32→                .summary
 33→                .clone()
 34→                .unwrap_or_else(|| manifest.id.as_str()[..8].to_string()),
 35→        });
 36→
 37→        // Add agent node + edge
 38→        let agent_id = format!("agent:{}", manifest.agent.name);
 39→        if seen_agents.insert(agent_id.clone()) {
 40→            graph.nodes.push(GraphNode {
 41→                id: agent_id.clone(),
 42→                node_type: NodeType::Agent,
 43→                label: manifest.agent.name.clone(),
 44→            });
 45→        }
 46→        graph.edges.push(GraphEdge {
 47→            from: engram_node_id.clone(),
 48→            to: agent_id,
 49→            edge_type: EdgeType::UsedAgent,
 50→        });
 51→
 52→        // Add file nodes + edges
 53→        for fc in &data.operations.file_changes {
 54→            let file_id = format!("file:{}", fc.path);
 55→            if seen_files.insert(file_id.clone()) {
 56→                graph.nodes.push(GraphNode {
 57→                    id: file_id.clone(),
 58→                    node_type: NodeType::File,
 59→                    label: fc.path.clone(),
 60→                });
 61→            }
 62→            graph.edges.push(GraphEdge {
 63→                from: engram_node_id.clone(),
 64→                to: file_id.clone(),
 65→                edge_type: EdgeType::TouchedFile,
 66→            });
 67→            graph.edges.push(GraphEdge {
 68→                from: file_id,
 69→                to: engram_node_id.clone(),
 70→                edge_type: EdgeType::ModifiedBy,
 71→            });
 72→        }
 73→
 74→        // Add commit nodes + edges
 75→        for sha in &data.lineage.git_commits {
 76→            let commit_id = format!("commit:{}", &sha[..std::cmp::min(8, sha.len())]);
 77→            if seen_commits.insert(commit_id.clone()) {
 78→                graph.nodes.push(GraphNode {
 79→                    id: commit_id.clone(),
 80→                    node_type: NodeType::Commit,
 81→                    label: sha[..std::cmp::min(8, sha.len())].to_string(),
 82→                });
 83→            }
 84→            graph.edges.push(GraphEdge {
 85→                from: engram_node_id.clone(),
 86→                to: commit_id,
 87→                edge_type: EdgeType::ProducedBy,
 88→            });
 89→        }
 90→
 91→        // Add lineage edges
 92→        if let Some(parent) = &data.lineage.parent_engram {
 93→            let parent_node_id = format!("engram:{}", parent.as_str());
 94→            graph.edges.push(GraphEdge {
 95→                from: engram_node_id,
 96→                to: parent_node_id,
 97→                edge_type: EdgeType::FollowsFrom,
 98→            });
 99→        }
100→    }
101→
102→    Ok(graph)
103→}
