 11→/// Import a Claude Code session from a JSONL file.
 12→pub struct ClaudeCodeImporter;
 13→
 14→impl ClaudeCodeImporter {
 15→    /// Discover the Claude Code projects directory.
 16→    pub fn projects_dir() -> Option<PathBuf> {
 17→        dirs_for_claude_projects()
 18→    }
 19→
 20→    /// Discover all session files for a project.
 21→    pub fn discover_sessions(project_path: &Path) -> Result<Vec<PathBuf>, CaptureError> {
 22→        let project_key = path_to_claude_key(project_path);
 23→        let projects_dir = Self::projects_dir()
 24→            .ok_or_else(|| CaptureError::Import("Cannot find ~/.claude/projects".into()))?;
 25→        let project_dir = projects_dir.join(&project_key);
 26→
 27→        if !project_dir.exists() {
 28→            return Ok(Vec::new());
 29→        }
 30→
 31→        let mut sessions = Vec::new();
 32→        for entry in std::fs::read_dir(&project_dir).map_err(CaptureError::Io)? {
 33→            let entry = entry.map_err(CaptureError::Io)?;
 34→            let path = entry.path();
 35→            if path.extension().is_some_and(|e| e == "jsonl") && path.is_file() {
 36→                sessions.push(path);
 37→            }
 38→        }
 39→        sessions.sort();
 40→        Ok(sessions)
 41→    }
 42→
 43→    /// Import a single session JSONL file into an EngramData.
 44→    pub fn import_session(path: &Path) -> Result<EngramData, CaptureError> {
 45→        let content = std::fs::read_to_string(path).map_err(CaptureError::Io)?;
 46→        let source_hash = format!("{:x}", Sha256::digest(content.as_bytes()));
 47→        let mut data = parse_claude_code_session(&content)?;
 48→        data.manifest.source_hash = Some(source_hash);
 49→        Ok(data)
 50→    }
 51→}
