 53→/// Internal Claude Code JSONL entry.
 54→#[derive(Debug, Deserialize)]
 55→struct ClaudeEntry {
 56→    #[serde(rename = "type")]
 57→    entry_type: String,
 58→    #[serde(default)]
 59→    _uuid: Option<String>,
 60→    #[serde(default, rename = "parentUuid")]
 61→    _parent_uuid: Option<String>,
 62→    #[serde(default)]
 63→    timestamp: Option<String>,
 64→    #[serde(default)]
 65→    message: Option<ClaudeMessage>,
 66→    #[serde(default, rename = "isSidechain")]
 67→    is_sidechain: Option<bool>,
 68→}
 69→
 70→#[derive(Debug, Deserialize)]
 71→struct ClaudeMessage {
 72→    role: String,
 73→    #[serde(default)]
 74→    content: serde_json::Value,
 75→    #[serde(default)]
 76→    model: Option<String>,
 77→    #[serde(default)]
 78→    usage: Option<ClaudeUsage>,
 79→}
 80→
 81→#[derive(Debug, Deserialize)]
 82→struct ClaudeUsage {
 83→    #[serde(default)]
 84→    input_tokens: Option<u64>,
 85→    #[serde(default)]
 86→    output_tokens: Option<u64>,
 87→    #[serde(default)]
 88→    cache_creation_input_tokens: Option<u64>,
 89→    #[serde(default)]
 90→    cache_read_input_tokens: Option<u64>,
 91→}
 92→
 93→fn parse_claude_code_session(content: &str) -> Result<EngramData, CaptureError> {
 94→    let mut entries = Vec::new();
 95→    let mut first_timestamp: Option<DateTime<Utc>> = None;
 96→    let mut last_timestamp: Option<DateTime<Utc>> = None;
 97→    let mut model_name: Option<String> = None;
 98→    let mut agent_version: Option<String> = None;
 99→    let mut token_usage = TokenUsage::default();
100→    let mut transcript_entries = Vec::new();
101→    let mut tool_calls = Vec::new();
102→    let mut file_changes = Vec::new();
103→    let mut original_request = String::new();
104→    let mut reasoning_text = String::new(); // Collect assistant text for insight extraction
105→    let mut first_assistant_text: Option<String> = None; // For interpreted_goal
106→
107→    // Parse all lines
108→    for line in content.lines() {
109→        if line.trim().is_empty() {
110→            continue;
111→        }
112→        match serde_json::from_str::<ClaudeEntry>(line) {
113→            Ok(entry) => entries.push(entry),
114→            Err(e) => {
115→                tracing::debug!("Skipping unparseable JSONL line: {e}");
116→            }
117→        }
118→    }
119→
120→    for entry in &entries {
121→        // Skip non-message entries
122→        if !matches!(entry.entry_type.as_str(), "user" | "assistant") {
123→            continue;
124→        }
125→
126→        // Skip sidechain messages
127→        if entry.is_sidechain == Some(true) {
128→            continue;
129→        }
130→
131→        // Parse timestamp
132→        let ts = entry
133→            .timestamp
134→            .as_deref()
135→            .and_then(|t| t.parse::<DateTime<Utc>>().ok());
136→
137→        if let Some(ts) = ts {
138→            if first_timestamp.is_none() {
139→                first_timestamp = Some(ts);
140→            }
141→            last_timestamp = Some(ts);
142→        }
143→
144→        let Some(msg) = &entry.message else {
145→            continue;
146→        };
147→
148→        // Extract model and version from first assistant message
149→        if msg.role == "assistant" && model_name.is_none() {
150→            model_name = msg.model.clone();
151→        }
152→
153→        // Accumulate token usage
154→        if let Some(usage) = &msg.usage {
155→            token_usage.input_tokens += usage.input_tokens.unwrap_or(0);
156→            token_usage.output_tokens += usage.output_tokens.unwrap_or(0);
157→            token_usage.cache_read_tokens += usage.cache_read_input_tokens.unwrap_or(0);
158→            token_usage.cache_write_tokens += usage.cache_creation_input_tokens.unwrap_or(0);
159→        }
160→
161→        // Process message content
162→        let role = match msg.role.as_str() {
163→            "user" => Role::User,
164→            "assistant" => Role::Assistant,
165→            _ => continue,
166→        };
167→
168→        // Content can be a string or array of content blocks
169→        match &msg.content {
170→            serde_json::Value::String(text) => {
171→                if role == Role::User && original_request.is_empty() {
172→                    original_request = text.clone();
173→                }
174→                if role == Role::Assistant {
175→                    reasoning_text.push_str(text);
176→                    reasoning_text.push('\n');
177→                    if first_assistant_text.is_none() && !text.trim().is_empty() {
178→                        first_assistant_text = Some(text.clone());
179→                    }
180→                }
181→                transcript_entries.push(TranscriptEntry {
182→                    timestamp: ts.unwrap_or_else(Utc::now),
183→                    role,
184→                    content: TranscriptContent::Text { text: text.clone() },
185→                    token_count: None,
186→                });
187→            }
188→            serde_json::Value::Array(blocks) => {
189→                for block in blocks {
190→                    let block_type = block.get("type").and_then(|t| t.as_str()).unwrap_or("");
191→
192→                    match block_type {
193→                        "text" => {
194→                            let text = block
195→                                .get("text")
196→                                .and_then(|t| t.as_str())
197→                                .unwrap_or("")
198→                                .to_string();
199→
200→                            if role == Role::User && original_request.is_empty() {
201→                                original_request = text.clone();
202→                            }
203→                            if role == Role::Assistant {
204→                                reasoning_text.push_str(&text);
205→                                reasoning_text.push('\n');
206→                                if first_assistant_text.is_none() && !text.trim().is_empty() {
207→                                    first_assistant_text = Some(text.clone());
208→                                }
209→                            }
210→
211→                            transcript_entries.push(TranscriptEntry {
212→                                timestamp: ts.unwrap_or_else(Utc::now),
213→                                role: role.clone(),
214→                                content: TranscriptContent::Text { text },
215→                                token_count: None,
216→                            });
217→                        }
218→                        "tool_use" => {
219→                            let tool_name = block
220→                                .get("name")
221→                                .and_then(|n| n.as_str())
222→                                .unwrap_or("unknown")
223→                                .to_string();
224→                            let tool_id = block
225→                                .get("id")
226→                                .and_then(|n| n.as_str())
227→                                .unwrap_or("")
228→                                .to_string();
229→                            let input = block
230→                                .get("input")
231→                                .cloned()
232→                                .unwrap_or(serde_json::Value::Null);
233→
234→                            // Track file operations
235→                            if matches!(tool_name.as_str(), "Write" | "Edit" | "NotebookEdit") {
236→                                if let Some(path) = input.get("file_path").and_then(|p| p.as_str())
237→                                {
238→                                    let change_type = if tool_name == "Write" {
239→                                        FileChangeType::Created
240→                                    } else {
241→                                        FileChangeType::Modified
242→                                    };
243→                                    if !file_changes.iter().any(|fc: &FileChange| fc.path == path) {
244→                                        file_changes.push(FileChange {
245→                                            path: path.to_string(),
246→                                            change_type,
247→                                            lines_added: None,
248→                                            lines_removed: None,
249→                                        });
250→                                    }
251→                                }
252→                            }
253→
254→                            tool_calls.push(ToolCall {
255→                                timestamp: ts.unwrap_or_else(Utc::now),
256→                                tool_name: tool_name.clone(),
257→                                input: input.clone(),
258→                                output_summary: None,
259→                                duration_ms: None,
260→                                is_error: false,
261→                            });
262→
263→                            transcript_entries.push(TranscriptEntry {
264→                                timestamp: ts.unwrap_or_else(Utc::now),
265→                                role: role.clone(),
266→                                content: TranscriptContent::ToolUse {
267→                                    tool_name,
268→                                    tool_id,
269→                                    input,
270→                                },
271→                                token_count: None,
272→                            });
273→                        }
274→                        "tool_result" => {
275→                            let tool_id = block
276→                                .get("tool_use_id")
277→                                .and_then(|n| n.as_str())
278→                                .unwrap_or("")
279→                                .to_string();
280→                            let output = block
281→                                .get("content")
282→                                .and_then(|c| c.as_str())
283→                                .unwrap_or("")
284→                                .to_string();
285→                            let is_error = block
286→                                .get("is_error")
287→                                .and_then(|e| e.as_bool())
288→                                .unwrap_or(false);
289→
290→                            transcript_entries.push(TranscriptEntry {
291→                                timestamp: ts.unwrap_or_else(Utc::now),
292→                                role: Role::Tool,
293→                                content: TranscriptContent::ToolResult {
294→                                    tool_id,
295→                                    output,
296→                                    is_error,
297→                                },
298→                                token_count: None,
299→                            });
300→                        }
301→                        "thinking" => {
302→                            let text = block
303→                                .get("thinking")
304→                                .and_then(|t| t.as_str())
305→                                .unwrap_or("")
306→                                .to_string();
307→                            if !text.is_empty() {
308→                                reasoning_text.push_str(&text);
309→                                reasoning_text.push('\n');
310→                                transcript_entries.push(TranscriptEntry {
311→                                    timestamp: ts.unwrap_or_else(Utc::now),
312→                                    role: role.clone(),
313→                                    content: TranscriptContent::Thinking { text },
314→                                    token_count: None,
315→                                });
316→                            }
317→                        }
318→                        _ => {}
319→                    }
320→                }
321→            }
322→            _ => {}
323→        }
324→    }
325→
326→    // Try to get version from the first JSON line
327→    if let Some(v) = content
328→        .lines()
329→        .next()
330→        .and_then(|line| serde_json::from_str::<serde_json::Value>(line).ok())
331→        .and_then(|v| v.get("version").and_then(|v| v.as_str()).map(String::from))
332→    {
333→        agent_version = Some(v);
334→    }
335→
336→    token_usage.total_tokens = token_usage.input_tokens
337→        + token_usage.output_tokens
338→        + token_usage.cache_read_tokens
339→        + token_usage.cache_write_tokens;
340→
341→    let now = Utc::now();
342→    let created_at = first_timestamp.unwrap_or(now);
343→    let finished_at = last_timestamp.unwrap_or(now);
344→
345→    let id = EngramId::new();
346→
347→    let manifest = Manifest {
348→        id,
349→        version: 1,
350→        created_at,
351→        finished_at: Some(finished_at),
352→        agent: AgentInfo {
353→            name: "claude-code".into(),
354→            model: model_name,
355→            version: agent_version,
356→        },
357→        git_commits: Vec::new(),
358→        token_usage,
359→        summary: if original_request.len() > 100 {
360→            Some(format!("{}...", &original_request[..100]))
361→        } else if original_request.is_empty() {
362→            Some("Imported Claude Code session".into())
363→        } else {
364→            Some(original_request.clone())
365→        },
366→        tags: Vec::new(),
367→        capture_mode: CaptureMode::Import,
368→        source_hash: None,
369→    };
370→
371→    // Extract dead ends and decisions from reasoning text
372→    let insights =
373→        crate::session::extractor::extract_insights(reasoning_text.as_bytes());
374→
375→    // Derive interpreted_goal from the first assistant response (truncated)
376→    let interpreted_goal = first_assistant_text.map(|t| {
377→        let trimmed = t.trim();
378→        if trimmed.len() > 200 {
379→            format!("{}...", &trimmed[..200])
380→        } else {
381→            trimmed.to_string()
382→        }
383→    });
384→
385→    let intent = Intent {
386→        original_request: if original_request.is_empty() {
387→            "Imported Claude Code session".into()
388→        } else {
389→            original_request
390→        },
391→        interpreted_goal,
392→        summary: manifest.summary.clone(),
393→        dead_ends: insights.dead_ends,
394→        decisions: insights.decisions,
395→    };
396→
397→    let operations = Operations {
398→        tool_calls,
399→        file_changes,
400→        shell_commands: Vec::new(),
401→    };
402→
403→    Ok(EngramData {
404→        manifest,
405→        intent,
406→        transcript: Transcript {
407→            entries: transcript_entries,
408→        },
409→        operations,
410→        lineage: Lineage::default(),
411→    })
412→}
