414→/// Convert a filesystem path to Claude Code's project key format.
415→/// /Users/sjonas/myproject -> -Users-sjonas-myproject
416→fn path_to_claude_key(path: &Path) -> String {
417→    let s = path.to_string_lossy();
418→    let s = s.trim_end_matches('/');
419→    s.replace('/', "-")
420→}
