 13→/// Result of a search query.
 14→#[derive(Debug, Clone)]
 15→pub struct SearchResult {
 16→    pub manifest: Manifest,
 17→    pub score: f32,
 18→    pub snippet: Option<String>,
 19→}
 20→
 21→/// Searches the engram index.
 22→pub struct EngramSearcher {
 23→    schema: EngramSchema,
 24→    index: Index,
 25→}
 26→
 27→impl EngramSearcher {
 28→    /// Open an existing index for reading.
 29→    pub fn open(path: &Path) -> Result<Self, QueryError> {
 30→        let schema = EngramSchema::new();
 31→        let index = Index::open_in_dir(path)?;
 32→        Ok(Self { schema, index })
 33→    }
 34→
 35→    /// Search engrams with a free-text query.
 36→    pub fn search(&self, query_str: &str, limit: usize) -> Result<Vec<SearchResult>, QueryError> {
 37→        let reader = self
 38→            .index
 39→            .reader_builder()
 40→            .reload_policy(ReloadPolicy::OnCommitWithDelay)
 41→            .try_into()?;
 42→        let searcher = reader.searcher();
 43→
 44→        let query_parser = QueryParser::for_index(
 45→            &self.index,
 46→            vec![
 47→                self.schema.intent_request,
 48→                self.schema.intent_summary,
 49→                self.schema.transcript_text,
 50→                self.schema.dead_ends,
 51→                self.schema.file_paths,
 52→            ],
 53→        );
 54→
 55→        let query = query_parser
 56→            .parse_query(query_str)
 57→            .map_err(|e| QueryError::Search(e.to_string()))?;
 58→
 59→        let top_docs = searcher.search(&query, &TopDocs::with_limit(limit))?;
 60→
 61→        let mut results = Vec::with_capacity(top_docs.len());
 62→        for (score, doc_address) in top_docs {
 63→            let doc: tantivy::TantivyDocument = searcher.doc(doc_address)?;
 64→
 65→            // Extract manifest JSON
 66→            let manifest_json = doc
 67→                .get_first(self.schema.manifest_json)
 68→                .and_then(|v| v.as_str())
 69→                .unwrap_or("{}");
 70→
 71→            let manifest: Manifest = serde_json::from_str(manifest_json)?;
 72→
 73→            // Extract snippet from intent summary
 74→            let snippet = doc
 75→                .get_first(self.schema.intent_summary)
 76→                .and_then(|v| v.as_str())
 77→                .map(|s| s.to_string());
 78→
 79→            results.push(SearchResult {
 80→                manifest,
 81→                score,
 82→                snippet,
 83→            });
 84→        }
 85→
 86→        Ok(results)
 87→    }
 88→
 89→    /// Search for engrams that modified a specific file path.
 90→    pub fn search_by_file(
 91→        &self,
 92→        file_path: &str,
 93→        limit: usize,
 94→    ) -> Result<Vec<SearchResult>, QueryError> {
 95→        let reader = self
 96→            .index
 97→            .reader_builder()
 98→            .reload_policy(ReloadPolicy::OnCommitWithDelay)
 99→            .try_into()?;
100→        let searcher = reader.searcher();
101→
102→        let query_parser = QueryParser::for_index(&self.index, vec![self.schema.file_paths]);
103→
104→        let query = query_parser
105→            .parse_query(file_path)
106→            .map_err(|e| QueryError::Search(e.to_string()))?;
107→
108→        let top_docs = searcher.search(&query, &TopDocs::with_limit(limit))?;
109→
110→        let mut results = Vec::with_capacity(top_docs.len());
111→        for (score, doc_address) in top_docs {
112→            let doc: tantivy::TantivyDocument = searcher.doc(doc_address)?;
113→            let manifest_json = doc
114→                .get_first(self.schema.manifest_json)
115→                .and_then(|v| v.as_str())
116→                .unwrap_or("{}");
117→            let manifest: Manifest = serde_json::from_str(manifest_json)?;
118→
119→            let snippet = doc
120→                .get_first(self.schema.intent_summary)
121→                .and_then(|v| v.as_str())
122→                .map(|s| s.to_string());
123→
124→            results.push(SearchResult {
125→                manifest,
126→                score,
127→                snippet,
128→            });
129→        }
130→
131→        Ok(results)
132→    }
133→}
