  8→/// A unique identifier for an engram.
  9→/// Generated as UUID v4 hex (no dashes), used as the ref path component.
 10→#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
 11→pub struct EngramId(pub String);
 12→
 13→impl EngramId {
 14→    pub fn new() -> Self {
 15→        Self(Uuid::new_v4().as_simple().to_string())
 16→    }
 17→
 18→    /// Parse and validate an ID string. Must be at least 2 characters.
 19→    pub fn parse(s: impl Into<String>) -> Result<Self, CoreError> {
 20→        let s = s.into();
 21→        if s.len() < 2 {
 22→            return Err(CoreError::InvalidId(format!(
 23→                "ID must be at least 2 characters, got {}",
 24→                s.len()
 25→            )));
 26→        }
 27→        Ok(Self(s))
 28→    }
 29→
 30→    /// The 2-char prefix used for fanout in refs/engrams/<ab>/<full-id>
 31→    pub fn fanout_prefix(&self) -> &str {
 32→        if self.0.len() >= 2 {
 33→            &self.0[..2]
 34→        } else {
 35→            "00"
 36→        }
 37→    }
 38→
 39→    pub fn as_str(&self) -> &str {
 40→        &self.0
 41→    }
 42→}
 43→
 44→impl Default for EngramId {
 45→    fn default() -> Self {
 46→        Self::new()
 47→    }
 48→}
 49→
 50→impl std::fmt::Display for EngramId {
 51→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 52→        write!(f, "{}", self.0)
 53→    }
 54→}
 55→
 56→impl From<String> for EngramId {
 57→    fn from(s: String) -> Self {
 58→        Self(s)
 59→    }
 60→}
