    let local_repo = Repository::init(local_tmp.path()).unwrap();
    local_repo
        .remote("origin", remote_tmp.path().to_str().unwrap())
        .unwrap();

    let storage = GitStorage::open(local_tmp.path()).unwrap();
    storage.init().unwrap();

    // Create an engram
