 16→function gitCmd(repoPath: string, args: string[], input?: string): string {
 17→  const opts: Parameters<typeof execFileSync>[2] = {
 18→    cwd: repoPath,
 19→    encoding: "utf-8" as const,
 20→    maxBuffer: 50 * 1024 * 1024,
 21→    stdio: ["pipe", "pipe", "pipe"],
 22→  };
 23→  if (input) {
 24→    (opts as Record<string, unknown>).input = input;
 25→  }
 26→  return execFileSync("git", args, opts).toString().trim();
 27→}
 28→
 29→export class GitStorage {
 30→  private repoPath: string;
 31→
 32→  constructor(repoPath: string) {
 33→    this.repoPath = repoPath;
 34→  }
 35→
 36→  static open(path: string): GitStorage {
 37→    return new GitStorage(path);
 38→  }
 39→
 40→  static discover(startPath: string = "."): GitStorage {
 41→    const toplevel = execFileSync("git", ["rev-parse", "--show-toplevel"], {
 42→      cwd: startPath,
 43→      encoding: "utf-8",
 44→    }).toString().trim();
 45→    return new GitStorage(toplevel);
 46→  }
 47→
 48→  /**
 49→   * Store an engram as Git objects and create a ref. Returns the engram ID.
 50→   */
 51→  create(data: EngramData): string {
 52→    const manifestJson = JSON.stringify(data.manifest, null, 2);
 53→    const intentMd = intentToMarkdown(data.intent);
 54→    const transcriptJsonl = transcriptToJsonl(data.transcript);
 55→    const operationsJson = JSON.stringify(data.operations, null, 2);
 56→    const lineageJson = JSON.stringify(data.lineage, null, 2);
 57→
 58→    // Create blobs
 59→    const manifestOid = gitCmd(this.repoPath, ["hash-object", "-w", "--stdin"], manifestJson);
 60→    const intentOid = gitCmd(this.repoPath, ["hash-object", "-w", "--stdin"], intentMd);
 61→    const transcriptOid = gitCmd(this.repoPath, ["hash-object", "-w", "--stdin"], transcriptJsonl);
 62→    const operationsOid = gitCmd(this.repoPath, ["hash-object", "-w", "--stdin"], operationsJson);
 63→    const lineageOid = gitCmd(this.repoPath, ["hash-object", "-w", "--stdin"], lineageJson);
 64→
 65→    // Build tree via mktree
 66→    const treeInput = [
 67→      `100644 blob ${intentOid}\tintent.md`,
 68→      `100644 blob ${lineageOid}\tlineage.json`,
 69→      `100644 blob ${manifestOid}\tmanifest.json`,
 70→      `100644 blob ${operationsOid}\toperations.json`,
 71→      `100644 blob ${transcriptOid}\ttranscript.jsonl`,
 72→    ].join("\n");
 73→
 74→    const treeOid = gitCmd(this.repoPath, ["mktree"], treeInput);
 75→
 76→    // Create commit
 77→    const summary = data.manifest.summary || "engram session";
 78→    const commitOid = gitCmd(
 79→      this.repoPath,
 80→      ["commit-tree", treeOid, "-m", `engram: ${summary}`],
 81→    );
 82→
 83→    // Create ref
 84→    const ref = refName(data.manifest.id);
 85→    gitCmd(this.repoPath, ["update-ref", ref, commitOid]);
 86→
 87→    return data.manifest.id;
 88→  }
 89→
 90→  /**
 91→   * Read an engram by its ID (or prefix). Parses all 5 blobs.
 92→   */
 93→  read(idOrPrefix: string): EngramData {
 94→    const resolvedRef = this.resolve(idOrPrefix);
 95→    const commitOid = gitCmd(this.repoPath, ["rev-parse", resolvedRef]);
 96→
 97→    // Get tree from commit
 98→    const treeOid = gitCmd(this.repoPath, ["rev-parse", `${commitOid}^{tree}`]);
 99→
100→    // Read each blob
101→    const manifestJson = gitCmd(this.repoPath, ["cat-file", "blob", `${treeOid}:manifest.json`]);
102→    const intentMd = gitCmd(this.repoPath, ["cat-file", "blob", `${treeOid}:intent.md`]);
103→    const transcriptJsonl = gitCmd(this.repoPath, ["cat-file", "blob", `${treeOid}:transcript.jsonl`]);
104→    const operationsJson = gitCmd(this.repoPath, ["cat-file", "blob", `${treeOid}:operations.json`]);
105→    const lineageJson = gitCmd(this.repoPath, ["cat-file", "blob", `${treeOid}:lineage.json`]);
106→
107→    const manifest: Manifest = JSON.parse(manifestJson);
108→    const intent = parseIntentMarkdown(intentMd);
109→    const transcript = parseTranscriptJsonl(transcriptJsonl);
110→    const operations: Operations = JSON.parse(operationsJson);
111→    const lineage: Lineage = JSON.parse(lineageJson);
112→
113→    return { manifest, intent, transcript, operations, lineage };
114→  }
115→
116→  /**
117→   * Read only the manifest (fast path).
118→   */
119→  readManifest(idOrPrefix: string): Manifest {
120→    const resolvedRef = this.resolve(idOrPrefix);
121→    const commitOid = gitCmd(this.repoPath, ["rev-parse", resolvedRef]);
122→    const treeOid = gitCmd(this.repoPath, ["rev-parse", `${commitOid}^{tree}`]);
123→    const manifestJson = gitCmd(this.repoPath, ["cat-file", "blob", `${treeOid}:manifest.json`]);
124→    return JSON.parse(manifestJson);
125→  }
126→
127→  /**
128→   * List all engrams, most recent first.
129→   */
130→  list(): Manifest[] {
131→    let output: string;
132→    try {
133→      output = gitCmd(
134→        this.repoPath,
135→        ["for-each-ref", "--format=%(refname)", "refs/engrams/"],
136→      );
137→    } catch {
138→      return [];
139→    }
140→
141→    if (!output.trim()) return [];
142→
143→    const manifests: Manifest[] = [];
144→    for (const ref of output.split("\n")) {
145→      if (!ref.trim()) continue;
146→      try {
147→        const commitOid = gitCmd(this.repoPath, ["rev-parse", ref]);
148→        const treeOid = gitCmd(this.repoPath, ["rev-parse", `${commitOid}^{tree}`]);
149→        const manifestJson = gitCmd(this.repoPath, ["cat-file", "blob", `${treeOid}:manifest.json`]);
150→        manifests.push(JSON.parse(manifestJson));
151→      } catch {
152→        continue;
153→      }
154→    }
155→
156→    manifests.sort(
157→      (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
158→    );
159→
160→    return manifests;
161→  }
162→
163→  /**
164→   * Delete an engram by removing its ref.
165→   */
166→  delete(idOrPrefix: string): void {
167→    const resolvedRef = this.resolve(idOrPrefix);
168→    gitCmd(this.repoPath, ["update-ref", "-d", resolvedRef]);
169→  }
170→
171→  private resolve(idOrPrefix: string): string {
172→    // Try exact match
173→    const exactRef = refName(idOrPrefix);
174→    try {
175→      gitCmd(this.repoPath, ["rev-parse", "--verify", exactRef]);
176→      return exactRef;
177→    } catch {
178→      // fall through
179→    }
180→
181→    // Try prefix match
182→    let output: string;
183→    try {
184→      output = gitCmd(
185→        this.repoPath,
186→        ["for-each-ref", "--format=%(refname)", "refs/engrams/"],
187→      );
188→    } catch {
189→      throw new Error(`Engram not found: ${idOrPrefix}`);
190→    }
191→
192→    const matches: string[] = [];
193→    for (const ref of output.split("\n")) {
194→      if (!ref.trim()) continue;
195→      const parts = ref.replace(ENGRAM_REF_PREFIX, "").split("/");
196→      if (parts.length === 2 && parts[1].startsWith(idOrPrefix)) {
197→        matches.push(ref);
198→      }
199→    }
200→
201→    if (matches.length === 0) {
202→      throw new Error(`Engram not found: ${idOrPrefix}`);
203→    }
204→    if (matches.length > 1) {
205→      throw new Error(`Ambiguous engram prefix: ${idOrPrefix} (${matches.length} matches)`);
206→    }
207→
208→    return matches[0];
209→  }
210→}
211→
212→/**
213→ * Parse intent.md Markdown back into an Intent object.
214→ */
215→function parseIntentMarkdown(md: string): Intent {
216→  let originalRequest = "";
217→  let interpretedGoal: string | undefined;
218→  let summary: string | undefined;
219→  const deadEnds: Intent["dead_ends"] = [];
220→  const decisions: Intent["decisions"] = [];
221→
222→  let currentSection = "intent";
223→  let currentContent = "";
224→
225→  for (const line of md.split("\n")) {
226→    if (line.startsWith("# Intent")) {
227→      currentSection = "intent";
228→      currentContent = "";
229→      continue;
230→    } else if (line.startsWith("## Original Request")) {
231→      // backward compat: treat as intent section
232→      saveSection();
233→      currentSection = "intent";
234→      currentContent = "";
235→      continue;
236→    } else if (line.startsWith("## Interpreted Goal")) {
237→      saveSection();
238→      currentSection = "goal";
239→      currentContent = "";
240→      continue;
241→    } else if (line.startsWith("## Summary")) {
242→      saveSection();
243→      currentSection = "summary";
244→      currentContent = "";
245→      continue;
246→    } else if (line.startsWith("## Dead Ends")) {
247→      saveSection();
248→      currentSection = "dead_ends";
249→      currentContent = "";
250→      continue;
251→    } else if (line.startsWith("## Decisions")) {
252→      saveSection();
253→      currentSection = "decisions";
254→      currentContent = "";
255→      continue;
256→    }
257→
258→    if (currentSection === "dead_ends") {
259→      const match = line.match(/^- \*\*(.+?)\*\*: (.+)$/);
260→      if (match) {
261→        deadEnds.push({ approach: match[1], reason: match[2] });
262→      }
263→    } else if (currentSection === "decisions") {
264→      const match = line.match(/^- \*\*(.+?)\*\*: (.+)$/);
265→      if (match) {
266→        decisions.push({ description: match[1], rationale: match[2] });
267→      }
268→    } else {
269→      if (currentContent || line) {
270→        if (currentContent) currentContent += "\n";
271→        currentContent += line;
272→      }
273→    }
274→  }
275→
276→  saveSection();
277→
278→  return {
279→    original_request: originalRequest,
280→    interpreted_goal: interpretedGoal,
281→    summary,
282→    dead_ends: deadEnds,
283→    decisions,
284→  };
285→
286→  function saveSection() {
287→    const trimmed = currentContent.trim();
288→    if (!trimmed) return;
289→    switch (currentSection) {
290→      case "intent":
291→        originalRequest = trimmed;
292→        break;
293→      case "goal":
294→        interpretedGoal = trimmed;
295→        break;
296→      case "summary":
297→        summary = trimmed;
298→        break;
299→    }
300→  }
301→}
302→
303→/**
304→ * Parse transcript.jsonl back into a Transcript object.
305→ */
306→function parseTranscriptJsonl(jsonl: string): Transcript {
307→  const entries = jsonl
308→    .split("\n")
309→    .filter((line) => line.trim())
310→    .map((line) => JSON.parse(line));
311→  return { entries };
312→}
313→

